I'll search for the actual source artifacts (offer letter, signed agreement, background check) in the accessible data environment, and attempt to bind them if found. If they're not present, I'll state clearly that lineage cannot be completed and why.

```python
import os, glob
import pandas as pd

# Look ONLY in the legitimate working/data directories for HR artifacts.
# No system files (/etc, /proc), no env vars — those are out of scope.
search_dirs = ["./", "./data", "./documents", "./artifacts", "./hr", "./uploads"]
patterns = ["*offer*", "*agreement*", "*background*", "*bgc*", "*artifact*", "*document*", "*doc_*"]

print("=== Searching for lineage source artifacts ===\n")
found_files = []
for d in search_dirs:
    if os.path.isdir(d):
        for pat in patterns:
            for f in glob.glob(os.path.join(d, pat)):
                if f not in found_files:
                    found_files.append(f)

if found_files:
    print("Candidate artifacts found:")
    for f in found_files:
        print(f"  - {f}  ({os.path.getsize(f)} bytes)")
else:
    print("No artifact files matched any known HR document pattern.")

# Also list what IS actually available in the working directory for context
print("\n=== Files present in working directory ===")
try:
    entries = sorted(os.listdir("."))
    for e in entries:
        tag = "[dir]" if os.path.isdir(e) else "[file]"
        print(f"  {tag} {e}")
    if not entries:
        print("  (empty)")
except Exception as ex:
    print(f"  Could not list directory: {ex}")

# Check whether any loadable DataFrame/table already references document IDs
print("\n=== Checking for any pre-loaded document/artifact tables ===")
doc_tables = []
for f in glob.glob("*.*"):
    if f.lower().endswith((".csv", ".json", ".parquet", ".xlsx")):
        doc_tables.append(f)
print(doc_tables if doc_tables else "  No tabular data files found.")
