if os.path.isdir(proj_dir):
    for root, dirs, files in os.walk(proj_dir):
        for f in files:
            fp = os.path.join(root, f)
            print(f"  [file] {fp} ({os.path.getsize(fp)} bytes)")
        for d in dirs:
            print(f"  [dir]  {os.path.join(root, d)}")
else:
    print("  Not found.")

# Search that directory + whole tree for HR artifact patterns (data files only)
print("\n=== HR artifact search (data files only, whole tree) ===")
hr_patterns = ["*offer*", "*agreement*", "*background*", "*bgc*", "*document*", "*artifact*", "*doc*.csv", "*doc*.json"]
